function roleLabel(role){return {customer:t('Mijoz'),restaurant_owner:t('Restoran egasi'),courier:t('Kuryer'),florist:t('Gulchi'),admin:t('Administrator')}[role]||t('Mijoz')}
function homeFor(user){return {admin:'/admin',restaurant_owner:'/manage',courier:'/courier',florist:'/florist'}[user.role]||'/discover'}
function readCoord(id){const v=$('#'+id)?.value;return v===undefined||v===''?null:Number(v)}
// The place is picked on the map only; the hidden inputs carry what the pin points at.
function coordinateFields(prefix,lat=null,lng=null){if(lat==null&&state.user?.addressLat!=null&&prefix!=='restaurant'){lat=state.user.addressLat;lng=state.user.addressLng}return ht`<input type="hidden" id="${prefix}Lat" value="${lat??''}"><input type="hidden" id="${prefix}Lng" value="${lng??''}"><div class="map-picker-host" data-map-picker="${prefix}"></div>`}
function bindCoordinateButtons(){document.querySelectorAll('[data-map-picker]').forEach(host=>{const p=host.dataset.mapPicker;window.RFMapPicker?.mount(host,{lat:readCoord(p+'Lat')??undefined,lng:readCoord(p+'Lng')??undefined,onChange:(lat,lng)=>{$('#'+p+'Lat').value=lat;$('#'+p+'Lng').value=lng},onError:notify})})}
// The main button opens the map app pinned on the restaurant; directions are the second option.
function mapCard(lat,lng,address){const valid=typeof lat==='number'&&typeof lng==='number'&&Number.isFinite(lat)&&Number.isFinite(lng)&&Math.abs(lat)<=90&&Math.abs(lng)<=180;const destination=valid?lat+','+lng:address;if(!valid)return ht`<p class="muted">Aniq xarita nuqtasi hali kiritilmagan.</p>${address?ht`<a class="quiet" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}">Manzilni xaritadan qidirish ↗</a>`:''}`;const box=[Math.max(-180,lng-.008),Math.max(-90,lat-.005),Math.min(180,lng+.008),Math.min(90,lat+.005)].join(',');return ht`<div class="map-card"><iframe title="${esc(address||t('Joylashuv xaritasi'))}" loading="lazy" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=${encodeURIComponent(box)}&layer=mapnik&marker=${lat}%2C${lng}"></iframe><div class="map-actions"><a class="primary" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(destination)}">📍 ${t(t('Xaritada ko‘rish'))}</a><a class="quiet" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}">${t(t('Yo‘nalish'))} ↗</a></div></div>`}
