 const leg=(cls,label,[a,b,phone])=>ht`<div class="courier-leg ${cls}"><small>${label}</small><p><b>${esc(a||'—')}</b></p>${b?ht`<p>${esc(b)}</p>`:''}${phone?ht`<p><a href="tel:${esc(phone)}">${esc(phone)}</a></p>`:''}</div>`;
 const card=(x,done=false)=>ht`<article class="courier-card"><h3>${esc(x.title)}</h3>${x.status?ht`<span class="badge">${esc(x.status)}</span>`:''}${leg('from',t(t('Qayerdan olish'))+(x.kind==='flower'?' ('+t(t('gul do‘koni'))+')':' ('+t(t('restoran'))+')'),x.from)}${leg('to',t(t('Qayerga yetkazish')),x.to)}${x.note?ht`<p class="muted">${esc(x.note)}</p>`:''}${done?'':ht`<div class="courier-actions">${x.to[2]?ht`<a class="quiet" href="tel:${esc(x.to[2])}">📞 ${t(t('Qo‘ng‘iroq qilish'))}</a>`:''}<a class="quiet" href="${esc(x.map)}" target="_blank" rel="noopener">🗺️ ${t(t('Xaritada ko‘rish'))}</a>${x.action?ht`<button type="button" class="primary" data-courier="${x.kind}:${x.action[0]}:${esc(x.id)}">${esc(x.action[1])}</button>`:''}${x.track?ht`<a class="quiet" href="${x.track}">📍 ${t(t('GPS va tafsilotlar'))}</a>`:''}</div>`}</article>`;
 const feeSum=history.reduce((n,x)=>n+(x.fee||0),0);
