// Opens the menu as a side drawer (desktop) or a bottom sheet (phones), growing out of the button pressed.
// While the drawer is open the page behind it stays still (iOS ignores overflow:hidden on body, so the
// body is pinned at its scroll position and put back on close); only the drawer itself scrolls.
let lockedScroll=null,lockedHash='';
function lockPageScroll(){if(lockedScroll!==null)return;lockedScroll=window.scrollY;lockedHash=location.hash;document.documentElement.classList.add('rf-scroll-lock');document.body.classList.add('rf-scroll-lock');document.body.style.top=-lockedScroll+'px'}
function unlockPageScroll(){if(lockedScroll===null)return;const y=lockedScroll;lockedScroll=null;document.documentElement.classList.remove('rf-scroll-lock');document.body.classList.remove('rf-scroll-lock');document.body.style.top='';window.scrollTo(0,location.hash===lockedHash?y:0)}
function openDrawer(origin){const d=$('#drawer');if(d.open)return;lockPageScroll();d.showModal();window.RFMotion?.open(d,origin);window.RFMotion?.swipe(d,closeDrawer);$('#menuButton').setAttribute('aria-expanded','true');document.querySelector('.mobile-more')?.setAttribute('aria-expanded','true')}
// Bottom bar per role: customers get the shopping bar; owners, florists, couriers and the admin get the bar of
// their own panel, and the client cart button and AI assistant are hidden for them (body[data-zone=b2b]).
const B2B_ROLES=['restaurant_owner','florist','courier','admin'];
function navZone(){return B2B_ROLES.includes(state.user?.role)?'b2b':'client'}
function bottomItems(){const r=state.user?.role;return r==='restaurant_owner'?[['manage',t('Kabinet')],['pos',t('Kassa')],['camera',t('AI kamera')],['pricing',t('Tariflar')],['account',t('Profil')]]:r==='florist'?[['florist',t('Kabinet')],['flowers',t('Gullar')],['account',t('Profil')]]:r==='courier'?[['courier',t('Buyurtmalar')],['account',t('Profil')]]:r==='admin'?[['admin',t('Admin')],['manage',t('Restoranlar')],['blog-admin',t('Blog')],['account',t('Profil')]]:[['discover',t('Asosiy')],['flowers',t('Gullar')],['cart',t('Savat')],['bookings',t('Bronlarim')],['account',t('Profil')]]}
function mobileNavigation(){const root=$('#mobileNav');if(!root)return;root.hidden=false;document.body.dataset.zone=navZone();const items=bottomItems();root.style.setProperty('--nav-cols',String(items.length+1));const count=readCart()?.items.reduce((s,i)=>s+i.quantity,0)||0;const feedbackCount=document.querySelector('[data-feedback-cart-count]');if(feedbackCount){feedbackCount.textContent=String(count);feedbackCount.hidden=!count}root.innerHTML=items.map(([id,label])=>ht`<a href="#/${id}" ${routeName()===id?'aria-current="page"':''}><span aria-hidden="true">${navIcon(id)}</span>${esc(t(label))}${id==='cart'&&count?ht`<b>${count}</b>`:''}</a>`).join('')+ht`<button type="button" class="mobile-more" aria-haspopup="dialog" ${$('#drawer').open?'aria-expanded="true"':''}><span aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg></span>${esc(t(t('Ko‘proq')))}</button>`;root.querySelector('.mobile-more').onclick=e=>openDrawer(e.currentTarget)}
function bindMenuCart(r,menu){
 const form=$('#orderForm');if(!form)return;
 form.querySelector('.form').innerHTML=lh('<div class="menu-cart-actions"><a class="primary" href="#/cart">Savatga o‘tish →</a><button type="button" class="quiet" data-cart-sound aria-pressed="true"></button></div>');
 window.RFCartFX?.bindSound(form.querySelector('[data-cart-sound]'));
 const update=()=>{const cart=readCart(),items=cart?.restaurantId===r.id?cart.items:[];$('#orderTotal').textContent=t(t('Taomlar'))+': '+money(items.reduce((sum,i)=>sum+(menu.find(m=>m.id===i.id)?.price||0)*i.quantity,0));const badge=form.querySelector('[data-menu-cart-count]');if(badge)badge.textContent=(cart?.items||[]).reduce((n,i)=>n+i.quantity,0)};
 // Menu quantities are drafts. Only the explicit Add button commits a dish.
 form.oninput=e=>{if(e.target.matches?.('input.qty'))e.target.setCustomValidity('')};
 form.querySelectorAll('[data-menu-add]').forEach(button=>button.onclick=()=>{
  const dish=menu.find(m=>m.id===button.dataset.menuAdd),input=form.elements.namedItem(button.dataset.menuAdd),quantity=Number(input?.value);
  if(!dish?.available||!input||input.disabled)return;
  input.setCustomValidity('');
  if(!Number.isInteger(quantity)||quantity<1||quantity>20){input.setCustomValidity(t(t('1 dan 20 tagacha tanlang.')));input.reportValidity();return}
  const cart=readCart(),sameRestaurant=cart?.restaurantId===r.id,items=sameRestaurant?cart.items.map(i=>({...i})):[],existing=items.find(i=>i.id===dish.id);
  if((existing?.quantity||0)+quantity>20){input.setCustomValidity(t(t('Savatda bir taomdan ko‘pi bilan 20 ta bo‘lishi mumkin.')));input.reportValidity();return}
  window.RFCartFX?.arm();
  if(cart?.items.length&&!sameRestaurant&&!confirm(t(t('Boshqa restoran tanlandi. Avvalgi savat almashtirilsinmi?'))))return;
  if(existing)existing.quantity+=quantity;else items.push({id:dish.id,quantity});
  state.cart={restaurantId:r.id,items,fulfillment:(state.selectedFulfillment==='delivery'||catalogFilter.service==='delivery')&&r.delivery_enabled?'delivery':sameRestaurant?cart.fulfillment:'pickup'};
  saveCart();update();window.RFCartFX?.add(button)
 });
 form.onsubmit=e=>{e.preventDefault();location.hash='/cart'};update()
}
function cartQuote(cart,menu,r){const items=cart.items.map(i=>{const m=menu.find(m=>m.id===i.id&&m.restaurant_id===r.id&&m.available);return m?{...i,name:m.name,price:m.price}:null}),invalid=items.some(i=>!i),valid=items.filter(Boolean),subtotal=valid.reduce((s,i)=>s+i.price*i.quantity,0),fee=cart.fulfillment==='delivery'?Number(r.delivery_fee)||0:0;return {items:valid,invalid,subtotal,fee,total:subtotal+fee}}
async function cartPage(seq){await loadCatalog();if(seq!==state.seq)return;const cart=readCart(),r=state.catalog.find(r=>r.id===cart?.restaurantId);if(!cart?.items.length||!r){page(t('Savat'),empty(t('Savat bo‘sh'),t('Restoran menyusidan taom tanlang.'))+lh('<a class="primary" href="#/discover">Restoranlar</a>'));return}const q=cartQuote(cart,state.menu,r);page(t('Savat'),ht`<section class="panel compact"><h2>${esc(r.name)}</h2>${r.id.startsWith('rf-demo-')?lh('<p class="notice">DEMO: haqiqiy xizmat ko‘rsatilmaydi. Buyurtma va bronlar faqat sinov uchun.</p>'):''}<a class="link" href="#/restaurant/${encodeURIComponent(r.id)}">Menyuga qaytish</a>${r.booking_enabled===false?'':ht`<a class="quiet cart-book" href="#/restaurant/${encodeURIComponent(r.id)}" data-cart-book>📅 ${t(t('Shu taomlar bilan stol bron qilish'))}</a>`}${q.invalid?lh('<p class="notice">Ayrim taomlar mavjud emas. Ular savatdan olib tashlandi.</p>'):''}<div class="rows">${q.items.map(i=>ht`<div class="row"><div><strong>${esc(i.name)}</strong><p>${money(i.price)} × ${i.quantity}</p></div><label>Soni<input class="qty" type="number" min="0" max="20" value="${i.quantity}" data-cart-qty="${esc(i.id)}" aria-label="${esc(i.name)}"></label><button class="link" data-cart-remove="${esc(i.id)}">O‘chirish</button></div>`).join('')}</div><form id="checkoutForm" class="form"><label>BUYURTMA TURI<select id="cartFulfillment"><option value="pickup">Olib ketish</option>${r.delivery_enabled?lh('<option value="delivery">Yetkazib berish</option>'):''}</select></label><div id="cartSummary" aria-live="polite"></div><label>TELEFON<input name="phone" type="tel" value="${esc(state.user?.contactPhone||state.user?.phone||'')}" pattern="\\+998[0-9]{9}" placeholder="+998901234567" required></label><div id="cartDelivery" class="form" hidden>${coordinateFields('cart')}<label>UY, PODYEZD, MO‘LJAL (IXTIYORIY)<input id="cartAddress" maxlength="300" value="${esc(state.user?.address||'')}" placeholder="${esc(t(t('Masalan: 12-uy, 3-podyezd, 45-xonadon')))}"></label></div><p>Buyurtma restoran tasdig‘ini kutadi. To‘lov qabul qilish vaqtida.</p>${state.user?ht`<button class="primary" id="placeOrder">${r.is_demo?t(t('Demo buyurtmani sinash')):t(t('Buyurtma yuborish'))}</button>`:lh('<a class="primary" href="#/login">Buyurtma uchun kiring</a>')}<p id="cartMessage" role="status"></p></form></section>`);cart.items=q.items.map(({id,quantity})=>({id,quantity}));if(!r.delivery_enabled)cart.fulfillment='pickup';saveCart();if(!cart.items.length){await cartPage(seq);return}$('#cartFulfillment').value=cart.fulfillment;const summary=()=>{cart.fulfillment=$('#cartFulfillment').value;saveCart();const v=cartQuote(cart,state.menu,r);$('#cartSummary').innerHTML=ht`<div class="row"><span>Taomlar</span><strong>${money(v.subtotal)}</strong></div><div class="row"><span>Yetkazib berish</span><strong>${money(v.fee)}</strong></div><div class="row"><span>Xizmat haqi</span><strong>${money(0)}</strong></div><div class="row"><strong>Jami</strong><strong>${money(v.total)}</strong></div>`;$('#cartDelivery').hidden=cart.fulfillment!=='delivery';};summary();$('#cartFulfillment').onchange=summary;bindCoordinateButtons();document.querySelectorAll('[data-cart-qty]').forEach(input=>input.onchange=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<0||n>20){input.reportValidity();return}cart.items=cart.items.map(i=>i.id===input.dataset.cartQty?{...i,quantity:n}:i).filter(i=>i.quantity);saveCart();cartPage(seq)});document.querySelectorAll('[data-cart-remove]').forEach(b=>b.onclick=()=>{cart.items=cart.items.filter(i=>i.id!==b.dataset.cartRemove);saveCart();cartPage(seq)});$('#checkoutForm').onsubmit=async e=>{e.preventDefault();if(!state.user){location.hash='/login';return}if(r.is_demo||r.id.startsWith('rf-demo-')){const receipt=cartQuote(cart,state.menu,r);state.cart=null;localStorage.removeItem('rf-cart');page(t('Demo buyurtma'),ht`<section class="panel compact"><span class="demo-badge">DEMO</span><h2>${esc(r.name)}</h2><p>${t(t('Demo savat tekshirildi. Restoranga haqiqiy buyurtma yoki to‘lov yuborilmadi.'))}</p>${receipt.items.map(i=>ht`<p>${esc(i.name)} × ${i.quantity} — ${money(i.price*i.quantity)}</p>`).join('')}<strong>${t(t('Jami'))}: ${money(receipt.total)}</strong><p><a class="primary" href="#/discover">${t(t('Restoranlar'))}</a></p></section>`);mobileNavigation();return}const button=$('#placeOrder');button.disabled=true;try{const result=await api('/api/orders','POST',{restaurantId:r.id,items:cart.items,phone:e.currentTarget.elements.phone.value,fulfillment:cart.fulfillment,deliveryAddress:$('#cartAddress').value,deliveryLat:readCoord('cartLat'),deliveryLng:readCoord('cartLng')});state.cart=null;try{localStorage.removeItem('rf-cart')}catch{}notify(t('Buyurtma yuborildi: ')+money(result.total));location.hash='/tracking/'+encodeURIComponent(result.id)}catch(err){$('#cartMessage').textContent=err.message;button.disabled=false}}}
// Same rule as the API (booking-rules.ts): customers cancel until 2 hours before the start (Tashkent time).
function bookingCancellable(b,now=Date.now()){return Date.parse(b.date+'T'+String(b.slot).slice(0,5)+':00+05:00')-now>=2*3600000}
// Live countdown to an upcoming booking (Tashkent time), ticking every second while the page is open.
const bookingStart=b=>Date.parse(b.date+'T'+String(b.slot).slice(0,5)+':00+05:00');let countdownTimer=0;
function countdownText(ms){const s=Math.max(0,Math.floor(ms/1000)),d=Math.floor(s/86400),p=v=>String(v).padStart(2,'0');return(d?d+' '+t(t('kun'))+' ':'')+p(Math.floor(s%86400/3600))+':'+p(Math.floor(s%3600/60))+':'+p(s%60)}
function bookingCountdown(x){if(!['pending','confirmed'].includes(x.status)||x.checked_in_at)return'';const start=bookingStart(x);if(!(start>Date.now()))return'';return ht`<div class="booking-countdown" data-start="${start}"><p>⏳ ${t(t('Bron vaqtigacha'))}: <b class="cd-value">${countdownText(start-Date.now())}</b></p><small>${t(t('2 soat qolganda Call AI kelishingizni tasdiqlashni so‘raydi. 2 soatdan kam qolganda bron ilova orqali bekor qilinmaydi — kech bekor qilish va kelmaslik uchun kartadan jarima yechiladi.'))}</small></div>`}
function tickCountdowns(){clearInterval(countdownTimer);const tick=()=>{const all=document.querySelectorAll('.booking-countdown');if(!all.length){clearInterval(countdownTimer);return}all.forEach(el=>{const left=Number(el.dataset.start)-Date.now();el.querySelector('.cd-value').textContent=countdownText(left);el.classList.toggle('soon',left<2*3600000);if(left<=0)el.classList.add('now')})};tick();countdownTimer=setInterval(tick,1000)}
function deliveryHeadline(o){if(o.status==='cancelled')return '';const eta=o.eta_minutes,at=eta?new Date(Date.now()+eta*60000).toLocaleTimeString(RF_I18N.locale(),{hour:'2-digit',minute:'2-digit'}):'';const delivery=o.fulfillment==='delivery',name=o.courier_name?esc(o.courier_name):t(t('Kuryer'));
 const title=o.status==='completed'?(delivery?'✅ '+t(t('Yetkazildi. Yoqimli ishtaha!')):'✅ '+t(t('Yakunlangan'))):o.status==='pending'?'⏳ '+t(t('Restoran buyurtmani tasdiqlashi kutilmoqda')):!delivery?'👨‍🍳 '+t(t('Tayyorlanmoqda')):o.delivery_status==='picked_up'?'🛵 '+name+' '+t(t('yo‘lda')):o.delivery_status==='assigned'?'👨‍🍳 '+t(t('Tayyorlanmoqda'))+' · '+name+' '+t(t('taomni oladi')):'👨‍🍳 '+t(t('Tayyorlanmoqda'));
 return ht`<div class="delivery-headline"><strong>${title}</strong>${eta?ht`<span class="delivery-eta">≈ ${eta} ${t(t('daqiqa'))} · ${t(t('taxminan'))} ${esc(at)}</span>`:''}${delivery&&o.courier_phone&&o.status==='confirmed'&&o.delivery_status!=='unassigned'?ht`<a class="quiet" href="tel:${esc(o.courier_phone)}">📞 ${t(t('Kuryerga qo‘ng‘iroq'))}</a>`:''}</div>`}
function orderProgress(o){if(o.status==='cancelled')return lh('<p class="notice">Bekor qilingan</p>');const delivery=o.fulfillment==='delivery',steps=[t('Qabul qilindi'),t('Tayyorlanmoqda'),delivery?t('Kuryerda'):t('Olib ketishga tayyor'),delivery?t('Yetkazildi'):t('Yakunlangan')];if(!delivery)steps.splice(2,1);const current=o.status==='completed'?steps.length-1:o.delivery_status==='picked_up'?2:o.status==='confirmed'?1:0;return ht`<ol class="order-progress" style="grid-template-columns:repeat(${steps.length},1fr)">${steps.map((step,i)=>ht`<li class="${i<=current?'done':''}" ${i===current?'aria-current="step"':''}><span>${i<current?'✓':i+1}</span>${esc(t(step))}</li>`).join('')}</ol>${o.status==='pending'?lh('<small>Restoran tasdig‘i kutilmoqda.</small>'):''}`}

