async function blogAdmin(seq){if(state.user?.role!=='admin'){page(t('Blog boshqaruvi'),empty(t('Ruxsat yo‘q'),t('Bu bo‘lim faqat sayt administratoriga ochiq.')));return}const d=await api('/api/blog');if(seq!==state.seq)return;page(t('Blog boshqaruvi'),ht`<a href="#/admin">← Admin panel</a><section class="panel"><label>${t(t('Maqola tanlang'))}<select id="blogSelect"><option value="">${t(t('Yangi maqola'))}</option>${d.posts.map(p=>ht`<option value="${esc(p.id)}">${esc(p.lang+' · '+p.title+' · '+p.status)}</option>`).join('')}</select></label><div id="blogEditor"></div></section>`);const editor=()=>{const p=d.posts.find(p=>p.id===$('#blogSelect').value);$('#blogEditor').innerHTML=ht`<form id="blogForm" class="form"><label>${t(t('Sarlavha'))}<input name="title" maxlength="160" minlength="5" required value="${esc(p?.title||'')}"></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="100" required value="${esc(p?.slug||'')}"></label><p>${t(t('Tarjimalar uchun bir xil slug ishlating.'))}</p><label>${t(t('Sayt tili'))}<select name="lang">${['ru','uz','en'].map(l=>ht`<option ${l===(p?.lang||RF_I18N.lang)?'selected':''}>${l}</option>`).join('')}</select></label><label>${t(t('Qisqa tavsif'))}<textarea name="description" minlength="20" maxlength="320" required>${esc(p?.description||'')}</textarea></label><label>${t(t('Maqola matni'))}<textarea name="content" rows="18" minlength="100" maxlength="12000" required>${esc(p?.content||'')}</textarea></label><p>${t(t('Bo‘lim sarlavhasini ## bilan boshlang. Abzaslarni bo‘sh qator bilan ajrating. HTML ishlatilmaydi.'))}</p><label>${t(t('Holat'))}<select name="status"><option value="draft" ${p?.status!=='published'?'selected':''}>${t(t('Qoralama'))}</option><option value="published" ${p?.status==='published'?'selected':''}>${t(t('Nashr qilingan'))}</option></select></label><div class="row-actions"><button class="primary">${t(t('Maqolani saqlash'))}</button>${p?ht`<button type="button" class="quiet" id="deleteBlog">${t(t('O‘chirish'))}</button>${p.status==='published'?ht`<a href="#/help/blog/${esc(p.slug)}">${t(t('Ko‘rish'))} →</a>`:''}`:''}</div><p id="blogMessage" role="status"></p></form>`;$('#blogForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/blog','POST',{...Object.fromEntries(new FormData(e.currentTarget)),id:p?.id});notify(t('Saqlandi'));render()}catch(e){$('#blogMessage').textContent=e.message;button.disabled=false}};if($('#deleteBlog'))$('#deleteBlog').onclick=async()=>{if(!confirm(t(t('Maqola o‘chirilsinmi?'))))return;try{await api('/api/blog','POST',{action:'delete',id:p.id});render()}catch(e){notify(e.message)}}};$('#blogSelect').onchange=editor;editor()}

const helpCache=new Map();
async function helpCenter(seq){
 const route=routeName(),parts=location.hash.replace(/^#\/?/,'').split('/'),tab=route==='support'?'contact':route==='faq'?'faq':route==='blog'?'blog':['faq','blog','contact'].includes(parts[1])?parts[1]:'faq',slug=route==='blog'?parts[1]:parts[2];
 const tabs=ht`<nav class="help-tabs" aria-label="${t(t('Yordam markazi'))}">${[['faq',t('Savol va javoblar')],['blog',t('Blog maqolalari')],['contact',t('Aloqa')]].map(([id,label])=>ht`<a class="quiet ${tab===id?'selected':''}" href="#/help/${id}" ${tab===id?'aria-current="page"':''}>${t(label)}</a>`).join('')}</nav>`;
 const shell=body=>page(t('Yordam markazi'),ht`<section class="help-center"><p class="help-intro">${t(t('Savollarga javoblar, foydali maqolalar va biz bilan aloqa — bir joyda.'))}</p>${tabs}${body}</section>`);
 if(tab==='contact'){shell(ht`<div class="two"><section class="panel"><p class="eyebrow">${t(t('TELEFON'))}</p><h2 class="contact-detail">+998 99 384 73 84</h2><a class="primary" href="tel:+998993847384">${t(t('Qo‘ng‘iroq qilish'))}</a></section><section class="panel"><p class="eyebrow">EMAIL</p><h2 class="contact-detail">admin@restaurantfoods.online</h2><a class="primary" href="mailto:admin@restaurantfoods.online?subject=RestaurantFoods%20Support">${t(t('Email yozish'))}</a></section></div><section class="panel"><h3>${t(t('Murojaatingizda nimalarni yozish kerak?'))}</h3><p>${t(t('Restoran nomi, bron yoki buyurtma sanasi va muammo tavsifini kiriting. Parol va tasdiqlash kodlarini yubormang.'))}</p></section>`);return}
 // One render per visit: data comes from a short in-memory cache, and the loading line appears only
 // when the request is slow — no 'loading -> content' flash on every open.
 const key='/api/info?lang='+encodeURIComponent(RF_I18N.lang)+(tab==='blog'?'&section=blog'+(slug?'&slug='+encodeURIComponent(slug):''):''),hit=helpCache.get(key);let data;
 if(hit&&Date.now()-hit.at<300000)data=hit.data;else{const slow=setTimeout(()=>{if(seq===state.seq)shell(ht`<p role="status">${t(t('Yuklanmoqda…'))}</p>`)},250);try{data=await api(key)}finally{clearTimeout(slow)}helpCache.set(key,{at:Date.now(),data})}if(seq!==state.seq)return;
 if(tab==='faq'){shell(ht`<div class="help-faq">${data.faqs.map(([question,answer])=>ht`<details class="panel"><summary>${esc(question)}<span aria-hidden="true">＋</span></summary><p>${esc(answer)}</p></details>`).join('')}</div>`);return}
 if(slug){const post=data.post;if(!post){shell(empty(t('Maqola topilmadi.'),'')+ht`<a class="quiet" href="#/help/blog">← ${t(t('Blog maqolalari'))}</a>`);return}shell(ht`<article class="panel help-article"><a class="link" href="#/help/blog">← ${t(t('Blog maqolalari'))}</a><h2>${esc(post.title)}</h2><p>${esc(post.description)}</p><div class="separator"></div>${post.content.split(/\n\s*\n/).map(p=>p.startsWith('## ')?ht`<h3>${esc(p.slice(3))}</h3>`:ht`<p>${esc(p).replace(/\n/g,lh('<br>'))}</p>`).join('')}</article>`);return}
 shell(data.posts.length?ht`<div class="help-posts">${data.posts.map(post=>ht`<a class="panel help-post" href="#/help/blog/${encodeURIComponent(post.slug)}"><span class="eyebrow">${t(t('Blog maqolalari'))}</span><h2>${esc(post.title)}</h2><p>${esc(post.description)}</p><span class="link">${t(t('O‘qish'))} →</span></a>`).join('')}</div>`:empty(t('Maqolalar hali e’lon qilinmagan.'),''))
}
